-- Turns a database built from the oldest schema.sql in git (01e8904) back into
-- what the migrations were written against: the ten original tables, before
-- any migration. Generated by listing every table the migrations create and
-- every column they add to the original tables. Used by
-- run_security.sh legacy, to prove upgrade_all.sql brings a database of any
-- age up to date.
drop table if exists public.action_usage cascade;
drop table if exists public.ai_usage cascade;
drop table if exists public.ai_usage_global cascade;
drop table if exists public.app_config cascade;
drop table if exists public.blocks cascade;
drop table if exists public.collection_posts cascade;
drop table if exists public.collections cascade;
drop table if exists public.comment_reactions cascade;
drop table if exists public.conversation_members cascade;
drop table if exists public.conversations cascade;
drop table if exists public.feedback cascade;
drop table if exists public.message_reactions cascade;
drop table if exists public.messages cascade;
drop table if exists public.notifications cascade;
drop table if exists public.nutrition_cache cascade;
drop table if exists public.post_tags cascade;
drop table if exists public.push_tokens cascade;
drop table if exists public.reports cascade;
drop table if exists public.upload_usage cascade;
alter table public.comments drop column if exists image_url cascade;
alter table public.comments drop column if exists parent_id cascade;
alter table public.comments drop column if exists reply_to_user_id cascade;
alter table public.posts drop column if exists photo_height cascade;
alter table public.posts drop column if exists photo_width cascade;
alter table public.recipes drop column if exists nutrition cascade;
alter table public.recipes drop column if exists nutrition_source cascade;
alter table public.recipes drop column if exists servings cascade;
delete from storage.buckets where id <> 'photos';
